            ph = ghr
        if tv:
            idx = (row['train_pc'] ^ row['train_history']) & 0x7f
            c = pht[idx]
            if row['train_taken']:
                if c < 3:
                    pht[idx] = c + 1
            else:
                if c > 0:
                    pht[idx] = c - 1
        if tv and row.get('train_mispredicted'):
            ghr = ((row['train_history'] << 1) | row['train_taken']) & 0x7f
